---@class ParkourGameSelectLevel
local ParkourGameSelectLevel = Class("ParkourGameSelectLevel")


-- ======================================================================== 

-- 晚于 OverseaParkourMainlineDialog:Awake 被调用:
function ParkourGameSelectLevel:Start()
    --printError("ParkourGameSelectLevel -:- Start")

    ---@type ParkourFactory
    self.factory = ParkourFactory.New(self.controller.transform:Find('PoolRoot'))

    local mapName = "Level_Select"
    ---@type TrackMapReader
    self.trackMapReader =  TrackMapReader.New(self.factory, mapName)

    ---创建轨道
    ---@type Track[]
    self.tracks = {}
    ---@type UnityEngine.Transform
    local track1 = self.controller.transform:Find('Track1')
    local imgPaths = self.trackMapReader:ImgPaths()
    local speed1 = 1
    local bgImgTrack = self.factory:CreateTrack1(track1, 2, 28.8, speed1, imgPaths)
    table.insert(self.tracks, bgImgTrack)

    local track2 = self.controller.transform:Find('Track2')
    local middlePrefabs = self.trackMapReader:MiddlePrefabs()
    local speed2 = 2.5
    local middleTrack = self.factory:CreateTrack2(track2, middlePrefabs, 2,20, speed2)
    table.insert(self.tracks, middleTrack)

    local track3 = self.controller.transform:Find('Track3')
    self.trackMapReader.singleMapLoop = true  -- 选关界面 特有的
    local speed3 = 5
    local interactionTrack = self.factory:CreateInteractionTrackSegment(track3, 3, ParkourGameUtil.InteractionTrackWidth, self.trackMapReader, speed3 )
    table.insert(self.tracks, interactionTrack)
    
    self:RegisterEvent()
end


function ParkourGameSelectLevel:OnDestroy()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    for i, v in ipairs(self.tracks) do
        v:Delete()
    end
    self.tracks = nil
    self.trackMapReader:Delete()
    self.trackMapReader = nil
    self.factory:Delete()
    self.factory = nil
end

-- =======================================================

function ParkourGameSelectLevel:RegisterEvent()
    self.events = CfUtils.EventsDecorated({
        [ParkourGameUtil.Events.SelectLevelDraging] = Bind(self, self.OnDraging),
    })
end

function ParkourGameSelectLevel:OnDraging(distance)
    -- 可能已经离开选关页面了, 此函数还在被调用
    if isNull(Mgr.player) then 
        return
    end 

    distance = distance * 1.3 -- 因为 ui 元素 和 track 元素的移动存在误差...
    if distance >= 0 then
        self:MoveTrack(distance,1)
        Mgr.player:Move( -distance )
    else
        self:MoveTrack(-distance,-1)
        Mgr.player:Move( -distance )
    end
end


function ParkourGameSelectLevel:MoveTrackByTime(direction)
    for i, v in ipairs(self.tracks) do
        v:MoveTime(5, direction)
    end
end

function ParkourGameSelectLevel:MoveTrack(distance,direction)
    for i, v in ipairs(self.tracks) do
        v:Move(distance,direction)
    end
end



return ParkourGameSelectLevel